#!/usr/bin/env node
/**
 * QSkyway — build a city digital-twin (20 m height field) from OpenStreetMap.
 *
 * WHY THIS EXISTS: the three committed twins (Astana, NYC, Tokyo — 524 KB, the
 * foundation every route, ceiling check and justification document is computed
 * over) were generated on 2026-07-13 by throwaway scripts that were never
 * committed. Their own headers say "Generated by rebuild_tokyo.mjs" — a file
 * that does not exist in this repository. That means the module's most load-
 * bearing data could not be refreshed, audited against OSM, or extended to a
 * fourth city. Committed data whose provenance cannot be re-run is a claim we
 * cannot check; this script turns it back into one we can.
 *
 * Usage:
 *   node scripts/fetch-city-twin.mjs astana > src/routes/qskyway.city.ts
 *   node scripts/fetch-city-twin.mjs nyc    > src/routes/qskyway.city.nyc.ts
 *   node scripts/fetch-city-twin.mjs tokyo  > src/routes/qskyway.city.tokyo.ts
 *   node scripts/fetch-city-twin.mjs astana --compare   (diff vs committed, no output)
 *
 * HONEST SCOPE — read before regenerating anything:
 *  - OSM is a live database. Re-running this will NOT reproduce the 2026-07-13
 *    files byte-for-byte: buildings get added, heights get tagged. Use
 *    --compare to see the drift as a number before overwriting a twin.
 *  - Tokyo's committed twin carries MEASURED heights from MLIT Project PLATEAU
 *    (CityGML LOD2), which this script does NOT fetch — PLATEAU ships as per-ward
 *    GML archives, not a queryable API. Regenerating tokyo from OSM alone would
 *    silently DOWNGRADE it from measured heights to guessed ones while every
 *    number in the UI kept looking the same. The registry therefore marks tokyo
 *    `osmOnly: false` and the script refuses to emit it.
 */

const OVERPASS = [
  "https://overpass-api.de/api/interpreter",
  "https://overpass.kumi.systems/api/interpreter",
];

// Height model, mirroring src/routes/qskyway.ts (SRC_CLEARANCE is indexed by it):
//   hs 0 = measured  — explicit `height` tag
//   hs 1 = derived   — building:levels × METRES_PER_LEVEL
//   hs 2 = guessed   — blind default, deliberately the WORST confidence class
const METRES_PER_LEVEL = 3.2;
const DEFAULT_HEIGHT_M = 12;

// Projection must match projector() in src/routes/qskyway.ts exactly, or routes
// would be computed against a grid that does not line up with the buildings.
const M_PER_LAT = 110540;
const M_PER_LON_EQ = 111320;
const CELL = 20;

const CITIES = {
  astana: {
    name: "Астана — центр (бульвар Нуржол)",
    bbox: { minLat: 51.1183717, maxLat: 51.1356973, minLon: 71.4104119, maxLon: 71.4432041 },
    exportName: "CITY",
    committed: "qskyway.city.ts",
    osmOnly: true,
    // Vertiports are a PRODUCT placement decision (where an operator would put
    // pads), not an OSM fact — so they are config here, never re-derived.
    vertiports: [
      { c: 64, r: 44, x: 1290, y: 890 }, { c: 2, r: 93, x: 50, y: 1870 },
      { c: 2, r: 2, x: 50, y: 50 }, { c: 112, r: 93, x: 2250, y: 1870 },
      { c: 112, r: 2, x: 2250, y: 50 }, { c: 53, r: 93, x: 1070, y: 1870 },
      { c: 17, r: 48, x: 350, y: 970 },
    ],
    header: [
      "// QSkyway city digital-twin — real Astana buildings from OpenStreetMap (Overpass),",
      "// rasterized to a 20m height field. v2: per-building height provenance (hs) +",
      "// per-cell source grid + dataQuality summary. Regenerate with:",
      "//   node scripts/fetch-city-twin.mjs astana > src/routes/qskyway.city.ts",
      "/* eslint-disable */",
      "export interface CityData {",
      "  city: string;",
      "  bbox: { minLat: number; maxLat: number; minLon: number; maxLon: number };",
      "  meters: { w: number; h: number };",
      "  grid: { cols: number; rows: number; cell: number; heights: number[]; src: number[] };",
      "  buildings: { h: number; hs: number; r: number[][] }[];",
      "  vertiports: { c: number; r: number; x: number; y: number }[];",
      "  dataQuality: {",
      "    total: number; measured: number; derived: number; guessed: number;",
      "    measuredPct: number; realPct: number; source: string; note: string;",
      "  };",
      "}",
    ].join("\n"),
  },
  nyc: {
    name: "Нью-Йорк — Мидтаун (Манхэттен)",
    bbox: { minLat: 40.7474728, maxLat: 40.7629936, minLon: -74.0002478, maxLon: -73.9758674 },
    exportName: "CITY_NYC",
    committed: "qskyway.city.nyc.ts",
    osmOnly: true,
    vertiports: null, // read from the committed twin (see loadCommitted)
    header: [
      "// QSkyway city digital-twin — NYC Midtown (Manhattan), real OpenStreetMap buildings",
      "// (Overpass, ODbL), 20m height field. v2: height provenance + dataQuality.",
      "// Regenerate with:",
      "//   node scripts/fetch-city-twin.mjs nyc > src/routes/qskyway.city.nyc.ts",
      "/* eslint-disable */",
      'import type { CityData } from "./qskyway.city";',
    ].join("\n"),
  },
  tokyo: {
    name: "Токио — Ниси-Синдзюку",
    bbox: { minLat: 35.683592, maxLat: 35.6978747, minLon: 139.6879457, maxLon: 139.7037075 },
    exportName: "CITY_TOKYO",
    committed: "qskyway.city.tokyo.ts",
    // NOT regenerable from OSM alone: the committed twin uses PLATEAU LOD2
    // measured heights. See HONEST SCOPE above.
    osmOnly: false,
    vertiports: null,
    header: "",
  },
};

const cityId = process.argv[2];
const compareOnly = process.argv.includes("--compare");
const city = CITIES[cityId];
if (!city) {
  console.error(`unknown city "${cityId}" — known: ${Object.keys(CITIES).join(", ")}`);
  process.exit(1);
}
if (!city.osmOnly && !compareOnly) {
  console.error(
    `refusing to emit "${cityId}": its committed twin carries measured heights this script cannot fetch.\n` +
    `Emitting an OSM-only rebuild would silently downgrade height provenance while the UI kept looking identical.\n` +
    `Use --compare to measure the OSM-only gap without overwriting anything.`,
  );
  process.exit(2);
}

// ── projection ────────────────────────────────────────────────────────────────
const { minLat, maxLat, minLon, maxLon } = city.bbox;
const lat0 = (minLat + maxLat) / 2;
const mPerLon = M_PER_LON_EQ * Math.cos((lat0 * Math.PI) / 180);
const proj = (lon, lat) => [(lon - minLon) * mPerLon, (maxLat - lat) * M_PER_LAT];

const W = Math.floor((maxLon - minLon) * mPerLon);
const H = Math.floor((maxLat - minLat) * M_PER_LAT);
const COLS = Math.ceil(W / CELL);
const ROWS = Math.ceil(H / CELL);

// ── fetch ─────────────────────────────────────────────────────────────────────
const query = `[out:json][timeout:180];
(way["building"](${minLat},${minLon},${maxLat},${maxLon});
 relation["building"](${minLat},${minLon},${maxLat},${maxLon}););
out geom;`;

async function overpass() {
  let lastErr;
  for (const host of OVERPASS) {
    for (let attempt = 1; attempt <= 3; attempt++) {
      try {
        // Raw query body, not form-encoded: overpass-api.de answers 406 to the
        // form-encoded shape. A descriptive User-Agent is also expected — the
        // instance is a donated public service and identifying the client is
        // the price of using it politely.
        const res = await fetch(host, {
          method: "POST",
          body: query,
          headers: {
            "Content-Type": "text/plain",
            "User-Agent": "AEVION-QSkyway/1.0 (city twin builder; contact via github.com/Dossymbek281078/AEVION)",
          },
          signal: AbortSignal.timeout(240_000),
        });
        // 429/504 are Overpass telling us to wait, not that the data is absent.
        if (res.status === 429 || res.status === 504) throw new Error(`Overpass HTTP ${res.status} (busy)`);
        if (!res.ok) throw new Error(`Overpass HTTP ${res.status}`);
        const json = await res.json();
        if (!json.elements) throw new Error("Overpass returned no elements array");
        return json.elements;
      } catch (e) {
        lastErr = e;
        process.stderr.write(`  ${host} attempt ${attempt}: ${e.message}\n`);
        if (attempt < 3) await new Promise((r) => setTimeout(r, 15_000 * attempt));
      }
    }
  }
  throw lastErr;
}

// ── height extraction ─────────────────────────────────────────────────────────
// A tag may read "42", "42 m", "42.5m". Anything unparseable falls through to the
// next source rather than becoming NaN — a NaN height would rasterize to a hole
// in the obstacle grid, i.e. a corridor flown straight through a building.
function parseMetres(v) {
  if (typeof v !== "string") return null;
  const m = v.trim().match(/^(-?\d+(?:\.\d+)?)\s*m?$/i);
  if (!m) return null;
  const n = Number(m[1]);
  return Number.isFinite(n) && n > 0 ? n : null;
}

function heightOf(tags = {}) {
  const explicit = parseMetres(tags.height) ?? parseMetres(tags["building:height"]);
  if (explicit !== null) return { h: Math.round(explicit), hs: 0 };
  const levels = parseMetres(tags["building:levels"]);
  if (levels !== null) return { h: Math.round(levels * METRES_PER_LEVEL), hs: 1 };
  return { h: DEFAULT_HEIGHT_M, hs: 2 };
}

// ── build ─────────────────────────────────────────────────────────────────────
function toRing(geom) {
  const pts = (geom ?? []).filter((p) => p && Number.isFinite(p.lat) && Number.isFinite(p.lon));
  if (pts.length < 3) return null;
  return pts.map((p) => {
    const [x, y] = proj(p.lon, p.lat);
    return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
  });
}

// A building may be a way (one ring) or a multipolygon relation (several outer
// ways, often with inner courtyards). Concatenating a relation's members into a
// single ring — the obvious-looking one-liner — produces a polygon that zig-zags
// between unrelated wings of the building and blocks cells nothing stands on.
// Inner (courtyard) members are skipped rather than punched out: a courtyard
// wrongly marked solid is conservative for flight, the reverse is not.
function ringsOf(el) {
  if (el.type === "way") {
    const r = toRing(el.geometry);
    return r ? [r] : [];
  }
  return (el.members ?? [])
    .filter((m) => m.type === "way" && (m.role === "outer" || m.role === ""))
    .map((m) => toRing(m.geometry))
    .filter(Boolean);
}

// Even-odd point-in-polygon on the cell CENTRE. Chosen (over any-overlap) so a
// 20 m cell is marked blocked when the building actually occupies its middle;
// any-overlap would inflate every footprint by up to a cell in each direction
// and quietly make the city denser than it is.
function inRing(ring, x, y) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i], [xj, yj] = ring[j];
    if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

function rasterize(buildings) {
  const heights = new Array(COLS * ROWS).fill(0);
  const src = new Array(COLS * ROWS).fill(0);
  for (const b of buildings) {
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    for (const [x, y] of b.r) {
      if (x < minX) minX = x; if (x > maxX) maxX = x;
      if (y < minY) minY = y; if (y > maxY) maxY = y;
    }
    const c0 = Math.max(0, Math.floor(minX / CELL)), c1 = Math.min(COLS - 1, Math.floor(maxX / CELL));
    const r0 = Math.max(0, Math.floor(minY / CELL)), r1 = Math.min(ROWS - 1, Math.floor(maxY / CELL));
    for (let r = r0; r <= r1; r++) {
      for (let c = c0; c <= c1; c++) {
        if (!inRing(b.r, c * CELL + CELL / 2, r * CELL + CELL / 2)) continue;
        const i = r * COLS + c;
        // Tallest building wins the cell, and carries ITS provenance with it:
        // the clearance model must reflect the obstacle actually being cleared.
        if (b.h > heights[i]) { heights[i] = b.h; src[i] = b.hs; }
      }
    }
  }
  return { heights, src };
}

function loadCommitted(file) {
  const fs = require("node:fs");
  const path = new URL(`../src/routes/${file}`, import.meta.url);
  const text = fs.readFileSync(path, "utf8");
  const start = text.indexOf('{"city"');
  if (start < 0) throw new Error(`cannot locate data literal in ${file}`);
  return JSON.parse(text.slice(start, text.lastIndexOf("};") + 1));
}

const { createRequire } = await import("node:module");
const require = createRequire(import.meta.url);

process.stderr.write(`QSkyway twin: ${cityId} — querying Overpass…\n`);
const elements = await overpass();

const buildings = [];
// Parallel array, diagnostics only — never emitted, so the twin keeps exactly
// the shape src/routes/qskyway.ts already consumes.
const meta = [];
for (const el of elements) {
  const { h, hs } = heightOf(el.tags);
  for (const r of ringsOf(el)) {
    buildings.push({ h, hs, r });
    meta.push({ id: `${el.type}/${el.id}`, name: el.tags?.name ?? el.tags?.["name:en"] ?? null });
  }
}
if (!buildings.length) throw new Error("Overpass returned no usable building footprints for this bbox");

const { heights, src } = rasterize(buildings);

const measured = buildings.filter((b) => b.hs === 0).length;
const derived = buildings.filter((b) => b.hs === 1).length;
const guessed = buildings.filter((b) => b.hs === 2).length;
const total = buildings.length;
const round1 = (n) => Math.round(n * 10) / 10;

const committed = loadCommitted(city.committed);

if (compareOnly) {
  const cg = committed.grid;
  let cellsChanged = 0, blockedNow = 0, blockedBefore = 0;
  // Direction matters far more than the raw diff. A cell the twin calls EMPTY
  // that OSM now shows built on is an obstacle the router does not know about —
  // the twin would happily plan a corridor through it. The opposite direction
  // (twin blocked, OSM empty) only costs a detour.
  let unknownObstacle = 0, staleObstacle = 0, taller = 0;
  for (let i = 0; i < cg.heights.length; i++) {
    const now = heights[i] ?? 0, before = cg.heights[i];
    if (before > 0) blockedBefore++;
    if (now > 0) blockedNow++;
    if (now !== before) cellsChanged++;
    if (before === 0 && now > 0) unknownObstacle++;
    else if (before > 0 && now === 0) staleObstacle++;
    else if (now > before) taller++;
  }
  const pct = (n, d) => `${round1((100 * n) / Math.max(1, d))}%`;

  // A count produced by my own rasterizer proves little on its own. Name the
  // buildings standing on cells the twin calls empty, so a human can check the
  // finding against OSM instead of trusting it.
  // Where the unknown obstacles sit decides what this is. Clustered on the
  // border = an edge artefact of one of the two pipelines. Spread through the
  // interior = the committed twin is genuinely missing buildings. Sampling the
  // first N would have answered "row 0" purely because that is where scanning
  // starts, so spread the samples and count the split explicitly.
  const unknownIdx = [];
  for (let i = 0; i < cg.heights.length; i++) {
    if (cg.heights[i] === 0 && (heights[i] ?? 0) > 0) unknownIdx.push(i);
  }
  const isEdge = (i) => {
    const c = i % cg.cols, r = Math.floor(i / cg.cols);
    return c === 0 || r === 0 || c === cg.cols - 1 || r === cg.rows - 1;
  };
  const edgeCount = unknownIdx.filter(isEdge).length;
  // Which source the unknown obstacle comes from is the diagnosis: if most sit
  // on multipolygon relations, the pipeline that produced the committed twin
  // was querying ways only, and the gap is systematic rather than drift.
  const relCells = unknownIdx.filter((i) => {
    const c = i % cg.cols, r = Math.floor(i / cg.cols);
    const x = c * CELL + CELL / 2, y = r * CELL + CELL / 2;
    const b = buildings.findIndex((bd) => bd.h === heights[i] && inRing(bd.r, x, y));
    return b >= 0 && meta[b].id.startsWith("relation/");
  }).length;

  const samples = [];
  const step = Math.max(1, Math.floor(unknownIdx.length / 6));
  for (let k = 0; k < unknownIdx.length && samples.length < 6; k += step) {
    const i = unknownIdx[k];
    const c = i % cg.cols, r = Math.floor(i / cg.cols);
    const x = c * CELL + CELL / 2, y = r * CELL + CELL / 2;
    const b = buildings.findIndex((bd) => bd.h === heights[i] && inRing(bd.r, x, y));
    if (b >= 0) samples.push(`    cell ${c},${r} h=${heights[i]}m  ${meta[b].id}${meta[b].name ? ` — ${meta[b].name}` : ""}`);
  }
  process.stderr.write(
    `\n── ${cityId}: OSM today vs committed twin (${committed.dataQuality.source}) ──\n` +
    `grid                ${COLS}×${ROWS} vs ${cg.cols}×${cg.rows}${COLS === cg.cols && ROWS === cg.rows ? "  ✓ same" : "  ✗ DIFFERENT"}\n` +
    `buildings           ${total} vs ${committed.buildings.length}\n` +
    `measured heights    ${measured} (${pct(measured, total)}) vs ${committed.dataQuality.measured} (${committed.dataQuality.measuredPct}%)\n` +
    `real (meas+derived) ${pct(measured + derived, total)} vs ${committed.dataQuality.realPct}%\n` +
    `blocked cells       ${blockedNow} vs ${blockedBefore}\n` +
    `cells differing     ${cellsChanged} of ${cg.heights.length} (${pct(cellsChanged, cg.heights.length)})\n` +
    `\n  ⚠ twin EMPTY, OSM built   ${unknownObstacle}  ← obstacles the router cannot see\n` +
    `      on the grid border     ${edgeCount} (${pct(edgeCount, unknownObstacle)}) — the rest are interior, so not an edge artefact\n` +
    `      from multipolygons     ${relCells} (${pct(relCells, unknownObstacle)}) — building relations, i.e. large complexes\n` +
    `    twin built, OSM empty    ${staleObstacle}  (costs a detour, not a collision)\n` +
    `    both built, OSM taller   ${taller}\n` +
    (samples.length ? `\n  buildings on cells the twin calls empty (verifiable in OSM):\n${samples.join("\n")}\n` : "") +
    `\n` +
    `Drift is expected — OSM is live. Judge by whether provenance IMPROVED\n` +
    `(more measured heights) before overwriting a committed twin, and treat a\n` +
    `large "twin EMPTY, OSM built" count as a safety finding, not a diff.\n`,
  );
  process.exit(0);
}

const data = {
  city: city.name,
  bbox: city.bbox,
  meters: { w: W, h: H },
  grid: { cols: COLS, rows: ROWS, cell: CELL, heights, src },
  buildings,
  vertiports: city.vertiports ?? committed.vertiports,
  dataQuality: {
    total, measured, derived, guessed,
    measuredPct: round1((100 * measured) / total),
    realPct: round1((100 * (measured + derived)) / total),
    source: "OpenStreetMap (Overpass, ODbL)",
    note: "hs 0=измерено(height tag) 1=выведено(levels×3.2) 2=угадано(дефолт 12м). Апгрейд LiDAR/LOD2/3D Tiles повышает measuredPct и снижает страховочный просвет.",
  },
};

process.stdout.write(`${city.header}\nexport const ${city.exportName}: CityData = ${JSON.stringify(data)};\n`);
process.stderr.write(
  `done: ${total} buildings, ${measured} measured (${data.dataQuality.measuredPct}%), grid ${COLS}×${ROWS}\n`,
);
